"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["85459"],{42053(e,n,t){t.r(n),t.d(n,{metadata:()=>i,default:()=>d,frontMatter:()=>r,contentTitle:()=>o,toc:()=>c,assets:()=>l});var i=JSON.parse('{"id":"nhcx/v1/concepts/claim-settlement","title":"Claim settlement","description":"The ten steps of a health insurance claim, the parties to it, and the email-and-portal mechanism NHCX replaces.","source":"@site/docs/nhcx/v1/concepts/claim-settlement.md","sourceDirName":"nhcx/v1/concepts","slug":"/nhcx/v1/concepts/claim-settlement","permalink":"/docs/pr-10/docs/nhcx/v1/concepts/claim-settlement","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1789025594000,"sidebarPosition":3,"frontMatter":{"title":"Claim settlement","sidebar_label":"Claim settlement","description":"The ten steps of a health insurance claim, the parties to it, and the email-and-portal mechanism NHCX replaces.","verification":"unverified","source":"NHCX Documentation v1.5.0; NHCX Guide for Providers (NHA)","sidebar_position":3},"sidebar":"nhcx-v1-overview","previous":{"title":"What NHCX is","permalink":"/docs/pr-10/docs/nhcx/v1/concepts/what-nhcx-is"},"next":{"title":"The NHCX way","permalink":"/docs/pr-10/docs/nhcx/v1/concepts/nhcx-way-of-claim-settlement"}}'),a=t(62540),s=t(43023);let r={title:"Claim settlement",sidebar_label:"Claim settlement",description:"The ten steps of a health insurance claim, the parties to it, and the email-and-portal mechanism NHCX replaces.",verification:"unverified",source:"NHCX Documentation v1.5.0; NHCX Guide for Providers (NHA)",sidebar_position:3},o="Claim settlement",l={},c=[{value:"In short",id:"in-short",level:2},{value:"What is health insurance?",id:"what-is-health-insurance",level:2},{value:"What is an insurance claim?",id:"what-is-an-insurance-claim",level:2},{value:"Types of health insurance claim",id:"types-of-health-insurance-claim",level:2},{value:"Participants",id:"participants",level:2},{value:"Claim settlement process",id:"claim-settlement-process",level:2},{value:"Current mechanism for claim settlement",id:"current-mechanism-for-claim-settlement",level:2}];function h(e){let n={h1:"h1",h2:"h2",header:"header",li:"li",mermaid:"mermaid",ol:"ol",p:"p",strong:"strong",ul:"ul",...(0,s.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n.header,{children:(0,a.jsx)(n.h1,{id:"claim-settlement",children:"Claim settlement"})}),"\n",(0,a.jsx)(n.p,{children:"Claim settlement is the end-to-end process by which a policyholder's or treating hospital's request for payment of medical expenses is evaluated, approved, and fulfilled by the insurance company or its authorised representative. It begins when a formal claim is raised, either cashless at the point of care or as a reimbursement after discharge. It ends when the agreed amount is disbursed to the hospital or refunded to the policyholder. The process involves verifying the validity of the policy, confirming the medical necessity of the treatment, checking the claim against applicable sum assured limits or package rates, and finally releasing payment. A smooth and transparent claim settlement process is central to the value of health insurance, ensuring that policyholders receive the financial protection they were promised without undue delay or documentation burden."}),"\n",(0,a.jsx)(n.h2,{id:"in-short",children:"In short"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"A claim runs from intimation to payment in ten steps, cashless or as a reimbursement."}),"\n",(0,a.jsx)(n.li,{children:"A Provider is the treating hospital's software; a Payer is the insurer's, or a TPA acting for one."}),"\n",(0,a.jsx)(n.li,{children:"Today most of this runs over email and some 30-odd insurer portals."}),"\n",(0,a.jsx)(n.li,{children:"That model gave traceability per claim, and made handling many insurers a complex affair."}),"\n"]}),"\n",(0,a.jsx)(n.h2,{id:"what-is-health-insurance",children:"What is health insurance?"}),"\n",(0,a.jsx)(n.p,{children:"Health insurance, or an Insurance Policy, is a contract between an individual and a promisor where the latter pledges to pay the individual's medical bills up to a set limit in case of any ailment. The individual is commonly known as a policyholder or beneficiary, whereas the promisor can be an insurance company acting by itself or on behalf of a government, organisation or corporate entity. It protects personal savings from being drained by unexpected hospital stays, surgeries, and medicines."}),"\n",(0,a.jsx)(n.h2,{id:"what-is-an-insurance-claim",children:"What is an insurance claim?"}),"\n",(0,a.jsx)(n.p,{children:"A health insurance claim is a formal request by a policyholder, or by the treating hospital, asking for payment or refund of money for medical care. It goes to an insurance company acting by itself or on behalf of a government, organisation or corporate entity."}),"\n",(0,a.jsx)(n.h2,{id:"types-of-health-insurance-claim",children:"Types of health insurance claim"}),"\n",(0,a.jsxs)(n.ol,{children:["\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Cashless."})," A patient who is a beneficiary of a policy can avail treatment in a hospital without paying any amount out of pocket. That applies where the hospital is under a Preferred Network for the insurance company with an existing agreement executed between them, or is empanelled under a specific scheme governing the policy. The amount of expenses incurred during treatment is capped either by the Sum Assured under the policy or by mutually agreed Package Rates earmarked for a specific medical or surgical procedure."]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Reimbursement."})," The patient pays the bills directly to the treating hospital and later gets the amount reimbursed by the insurance company upon submission of all relevant documents. This is common practice where the treating hospital is not part of the Preferred Network for that insurance company. NHCX has begun to define reimbursement flows on the network, but this documentation does not cover them yet."]}),"\n"]}),"\n",(0,a.jsx)(n.h2,{id:"participants",children:"Participants"}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Who is a Provider?"}),"\nA Provider is the treating hospital providing healthcare services to a patient who is a beneficiary under a policy. The HMIS software that the Provider hospital uses is known as the Provider Application, commonly shortened to just the Provider."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Who is a Payer?"}),"\nA Payer is the insurance company that has issued the policy and is liable to make payments for medical expenses incurred in treating the policyholder. In some cases independent TPAs act on behalf of an insurance company to settle such medical bills and thereby assume the role of a Payer. Likewise, the software used by a Payer is called the Payer Application, or simply the Payer."]}),"\n",(0,a.jsx)(n.h2,{id:"claim-settlement-process",children:"Claim settlement process"}),"\n",(0,a.jsx)(n.p,{children:"This is a two-way communication between the hospital and the insurance company, that is, between Provider and Payer. It concerns the policy, the treatment rendered to the policyholder patient, and the payment of hospital bills upon proper scrutiny of all relevant documents. It starts with the treating hospital conveying to the insurance company an imminent claim for a patient who is to be admitted for treatment. It runs until payment is realised for all expenses incurred while treating that patient."}),"\n",(0,a.jsx)(n.p,{children:"The entire journey of claim settlement can be broken down into the following distinct flows or use cases."}),"\n",(0,a.jsxs)(n.ol,{children:["\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Intimation."})," The hospital informs the insurance company that a patient holding one of its policies is about to be treated for the ailments diagnosed."]}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Policy verification by the hospital."})," The hospital confirms that the patient holds a valid policy from that insurance company, and that the ailments to be treated are covered under it."]}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Beneficiary and tie-up verification by the insurer."})," The insurance company confirms that a bonafide policyholder has turned up for treatment, and that a proper tie-up is in place with the hospital for providing cashless treatment."]}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Treatment plan intimation."})," The hospital sets out the plan of treatment, the procedures to be carried out if any, and the expected length of stay necessary for treatment."]}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Preauthorisation."}),' Satisfied with the sanctity of the case, the insurance company sends a preliminary approval, commonly known as Preauthorisation or "PreAuth", authorising the hospital to go ahead with treatment. The patient is thereby admitted.']}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Enhancement."}),' During the course of treatment the hospital may return to the insurance company to notify it that additional procedures may need to be administered, or that an extension of stay is required. This is commonly known as an "Enhancement".']}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Discharge and document submission."})," On discharge, the hospital submits all necessary documents to the insurance company, including consultation and clinical notes, diagnostic reports, medication details, the discharge summary and all bills."]}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Query."}),' The insurance company may ask for further explanation, or for documents it deems would substantiate the claim and assist its adjudication. Such communication from the insurance company to the hospital is called a "Query".']}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Adjudication."}),' The insurance company carries out a final adjudication and conveys the outcome to the hospital, stating whether the claimed amount is "Granted", "Denied" or "Partially Granted", with reasons.']}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Payment."})," The insurance company pays the hospital the granted amount and notifies it of the banking transaction, along with other details such as taxation or deductions as applicable."]}),"\n"]}),"\n"]}),"\n",(0,a.jsx)(n.mermaid,{value:"sequenceDiagram\n  box rgb(220,239,227) Provider side\n    participant H as Hospital\n  end\n  box rgb(220,232,245) Payer side\n    participant I as Insurance company\n  end\n  H->>I: 1. Intimation\n  Note over H: 2. Checks the policy and what it covers\n  Note over I: 3. Checks the beneficiary and the tie-up\n  H->>I: 4. Treatment plan\n  I--\x3e>H: 5. Preauthorisation\n  H->>I: 6. Enhancement, if the case needs more\n  H->>I: 7. Discharge and documents\n  I--\x3e>H: 8. Query, if something is missing\n  H->>I: Answer to the query\n  I--\x3e>H: 9. Adjudication: granted, denied or partly granted\n  I--\x3e>H: 10. Payment and bank details"}),"\n",(0,a.jsx)(n.h2,{id:"current-mechanism-for-claim-settlement",children:"Current mechanism for claim settlement"}),"\n",(0,a.jsx)(n.p,{children:"Email has been by far the most prevalent practice for exchange of information between hospitals and insurance companies over decades. Tracking and tracing mail correspondence for a large number of patients is a tedious and time-consuming exercise. The absence of any dashboard makes it inconvenient for users at both Provider and Payer ends to identify immediate action items and act upon them. Insurance companies and TPAs have therefore come up with their own individual portals, where hospitals can identify a beneficiary using policy details, fetch basic insurance plans and upload documents. Although this model improved traceability for individual claims, handling policies from different insurance companies across some 30-odd portals makes it a complex affair."})]})}function d(e={}){let{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(h,{...e})}):h(e)}}}]);